begin;
set local lock_timeout='5s';
set local timezone='Asia/Taipei';
do $test$
declare actor uuid:='5926554a-b8cc-4756-8d66-0a9a0877f94e';project uuid:='ae4789ca-469e-495f-901e-a0f0e4bef90b';restricted uuid:='11131113-0000-4000-8000-000000000001';item uuid; cable uuid:='2cd07e17-d21c-4a6c-90c3-73c379de343f';supplier uuid;customer uuid;doc uuid:=gen_random_uuid();ret uuid:=gen_random_uuid();site_doc uuid:=gen_random_uuid();request uuid:=gen_random_uuid();rows jsonb;expected jsonb;res jsonb;payload jsonb;fail boolean;own_id uuid:=gen_random_uuid();other_id uuid:=gen_random_uuid();cal jsonb;
begin
 if current_database()<>'guc_construction_relink_20261113' then raise exception 'isolated fixture database required';end if;
 select id into item from public.inventory_items where inventory_status='active' and public.current_inventory_quantity(id)>10 order by id limit 1;
 select id into supplier from public.suppliers limit 1;select customer_id into customer from public.projects where id=project;
 if item is null or customer is null then raise exception 'fixture missing';end if;
 rows:=jsonb_build_array(jsonb_build_object('inventory_item_id',item,'quantity',1,'quantity_unit','package','note','same'),jsonb_build_object('inventory_item_id',item,'quantity',1,'quantity_unit','package','note','same'));
 res:=public.save_stock_receipt_document_v5(doc,true,'[]',current_date,supplier,rows,'{}','[]',actor);
 if (select count(*)from public.stock_receipts where receipt_document_id=doc)<>2 then raise exception 'receipt collapsed lines';end if;
 perform public.save_stock_receipt_document_v5(doc,true,'[]',current_date,supplier,rows,'{}','[]',actor);
 if (select count(*)from public.stock_receipts where receipt_document_id=doc)<>2 then raise exception 'receipt retry duplicated';end if;
 select jsonb_agg(jsonb_build_object('id',id,'row_version',row_version)),jsonb_agg(jsonb_build_object('id',id,'inventory_item_id',inventory_item_id,'quantity',2,'quantity_unit','package','note','same')) into expected,rows from public.stock_receipts where receipt_document_id=doc;
 perform public.save_stock_receipt_document_v5(doc,false,expected,current_date,supplier,rows,'{}','[]',actor);
 if (select sum(quantity)from public.stock_receipts where receipt_document_id=doc)<>4 then raise exception 'receipt edit lost rows';end if;
 rows:=jsonb_build_array(jsonb_build_object('inventory_item_id',item,'quantity',1,'quantity_unit','package','note','same'),jsonb_build_object('inventory_item_id',item,'quantity',1,'quantity_unit','package','note','same'));
 payload:=jsonb_build_object('document_id',ret,'request_id',request,'supplier_id',supplier,'return_date',current_date,'rows',rows,'customer_ids','[]'::jsonb,'customer_departments','[]'::jsonb,'receipt_metadata','{}'::jsonb);
 perform public.save_supplier_return_v1(actor,'create',payload);
 perform public.save_supplier_return_v1(actor,'create',payload);
 if (select count(*)from public.supplier_return_lines where document_id=ret)<>2 then raise exception 'supplier return duplicate rows/retry failed';end if;
 rows:=jsonb_build_array(jsonb_build_object('inventory_item_id',cable,'quantity',12,'quantity_unit','meter','is_remnant_box',true),jsonb_build_object('inventory_item_id',cable,'quantity',13,'quantity_unit','meter','is_remnant_box',true));
 perform public.save_site_return_v1(actor,site_doc,request,null,'create',current_date,customer,project,rows,'isolated regression');
 if (select count(*)from public.site_return_lines where document_id=site_doc)<>2 or (select sum(quantity)from public.site_return_lines where document_id=site_doc)<>25 then raise exception 'physical remnant boxes collapsed';end if;
 fail:=false;begin perform public.dashboard_calendar_v1(restricted,current_date,current_date);exception when others then fail:=true;end;
 if not fail then raise exception 'dashboard denied user accepted';end if;
 insert into public.role_permissions(role_code,module,can_view) values('diag_relink_restricted','dashboard',true),('diag_relink_restricted','worklogs',true) on conflict(role_code,module)do update set can_view=true;
 insert into public.work_assignments(id,project_id,assignee_user_id,created_by_user_id,assignment_type,instructions,status)values(own_id,project,restricted,actor,'general','calendar own regression','pending'),(other_id,project,actor,actor,'general','calendar other regression','pending');
 cal:=public.dashboard_calendar_v1(restricted,current_date,current_date);
 if not exists(select 1 from jsonb_array_elements(cal->'records')r where r->>'id'=own_id::text) or exists(select 1 from jsonb_array_elements(cal->'records')r where r->>'id'=other_id::text) then raise exception 'calendar owner boundary failed';end if;
 if exists(select 1 from jsonb_array_elements(cal->'records')r where r->>'assignment_type'='appointment') then raise exception 'calendar appointment permission leaked';end if;
 cal:=public.dashboard_calendar_v1(actor,current_date,current_date);
 if not exists(select 1 from jsonb_array_elements(cal->'records')r where r->>'id'=own_id::text) then raise exception 'authorized manager cannot see coworker';end if;
 fail:=false;begin perform public.dashboard_calendar_v1(actor,current_date,current_date+44);exception when others then fail:=true;end;
 if not fail then raise exception 'unbounded calendar range accepted';end if;
 if has_function_privilege('anon','public.dashboard_calendar_v1(uuid,date,date)','execute') or has_function_privilege('authenticated','public.dashboard_calendar_v1(uuid,date,date)','execute') then raise exception 'calendar actor spoof exposed';end if;
 raise notice 'Repeated receipt create/edit/retry, supplier return retry, separate physical boxes, manager/owner/denied calendar and bounded dates passed';
end $test$;
rollback;
